using System.Globalization;
using DigitalHeat.Gaming;
using DigitalHeat.Gaming.Monitor;
using Spectre.Console;
using Spectre.Console.Rendering;

// T-42 heat monitor: heat need of each node's site vs heat generated by the sessions reserved on it.
// Read-only towards Docker; reservations are SessionPlacement claims, never game launches.
CultureInfo.DefaultThreadCurrentCulture = CultureInfo.InvariantCulture;
CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;

string? rootArg = null, configArg = null, dateArg = null;
int initialSessions = 0;
bool showDetails = false, whatIf = false;
bool noDocker = false, startLive = false, once = false;
for (int i = 0; i < args.Length; i++)
{
    switch (args[i])
    {
        case "--root" when i + 1 < args.Length: rootArg = args[++i]; break;
        case "--config" when i + 1 < args.Length: configArg = args[++i]; break;
        case "--no-docker": noDocker = true; break;
        case "--live": startLive = true; break;
        case "--once": once = true; break;
        case "--details": showDetails = true; break;
        case "--what-if": whatIf = true; break;
        case "--date" when i + 1 < args.Length: dateArg = args[++i]; break;
        case "--reserve" when i + 1 < args.Length && int.TryParse(args[i + 1], out var count) && count >= 0 && count <= 100:
            initialSessions = count; i++; break;
        default:
            Console.Error.WriteLine("Usage: GamingHeatMonitor [--root <repo>] [--config <heat-monitor.json>] [--no-docker] [--live] [--once] [--date yyyy-MM-ddTHH:00] [--reserve 0..100] [--what-if] [--details]");
            return 2;
    }
}

MonitorSetup setup;
try
{
    string root = rootArg is not null ? Path.GetFullPath(rootArg) : MonitorSetup.FindRepositoryRoot();
    setup = MonitorSetup.Load(root, configArg ?? Path.Combine(root, "gaming", "deploy", "heat-monitor.json"));
    if (dateArg is not null) setup.IndexOf(dateArg);
    if (dateArg is not null && startLive) throw new ArgumentException("Choose --date replay or --live, not both.");
}
catch (Exception e) { Console.Error.WriteLine("Cannot start heat monitor: " + e.Message); return 1; }

var engine = setup.CreateEngine();
var log = new List<string>();
void Log(string message) { log.Add($"{DateTime.Now:HH:mm:ss}  {message}"); if (log.Count > 7) log.RemoveAt(0); }

// ---- time: replay (default, offline) or live ---------------------------------------------------
int index = setup.IndexOf(dateArg ?? setup.Config.ReplayStartLocal);
var history = new Stack<(int Index, EngineMemory Memory)>();
string mode = "replay";
engine.Begin(setup.ReplayHour(index));
Log($"Replay started at {setup.Axis[index]}, tanks empty. Press R to reserve a player session.");

using var http = new HttpClient();
http.DefaultRequestHeaders.UserAgent.ParseAdd("DigitalHeat-T41-heat-monitor/1.0");
var live = new LiveSources(setup, http);
Task<LiveHourResult>? liveTask = null;
bool liveIsAdvance = false;
int timeGeneration = 0, liveTaskGeneration = 0; // bumped by every jump/back/mode switch; stale fetches are ignored

void StartLiveFetch(bool advance)
{
    if (liveTask is not null) return;
    liveIsAdvance = advance;
    liveTaskGeneration = timeGeneration;
    liveTask = Task.Run(() => live.FetchAsync(DateTimeOffset.UtcNow));
    Log(advance ? "New hour: fetching live weather and price..." : "Fetching live weather (Open-Meteo) and price (ElCom)...");
}

void CompleteLiveFetch()
{
    if (liveTask is not { IsCompleted: true } task) return;
    liveTask = null;
    if (liveTaskGeneration != timeGeneration) { Log("[live] Ignored a fetch that finished after you changed time/mode."); return; }
    if (task.IsFaulted) { Log("[live] fetch failed: " + task.Exception!.GetBaseException().Message); return; }
    var result = task.Result;
    foreach (var w in result.Warnings) Log("[live] " + w);
    if (liveIsAdvance)
    {
        if (mode != "live" || engine.Current is not { } now || result.Hour.IntervalStartUtc <= now.IntervalStartUtc) return;
        double gapHours = (result.Hour.IntervalStartUtc - now.IntervalStartUtc).TotalHours;
        engine.Advance(result.Hour);
        Log($"[live] Closed hour, now {result.Hour.LocalLabel}." + (gapHours > 1
            ? $" Warning: {gapHours - 1:F0} h skipped (sleep/offline); only one hour of heat balance was counted." : ""));
    }
    else
    {
        timeGeneration++;
        var dropped = engine.Begin(result.Hour);
        mode = "live";
        history.Clear();
        Log($"[live] Live mode at {result.Hour.LocalLabel} (Europe/Zurich), tanks empty." + Dropped(dropped));
    }
}

// ---- Docker readiness ---------------------------------------------------------------------------
var probe = new DockerProbe(setup, new DockerCommandRunner());
IReadOnlyDictionary<string, DockerNodeState> docker = new Dictionary<string, DockerNodeState>();
Task<IReadOnlyDictionary<string, DockerNodeState>>? dockerTask = null;
DateTime nextProbe = DateTime.MinValue;
bool checkCapabilities = !whatIf;
TimeSpan probeInterval = TimeSpan.FromSeconds(5); // UI refresh choice, not a measurement.

void ApplyReadiness()
{
    foreach (var node in setup.Config.Nodes)
    {
        bool running = noDocker || (docker.TryGetValue(node.NodeId, out var s) && s.ContainerRunning);
        bool capable = !checkCapabilities || !setup.IncompatibleNodes.ContainsKey(node.NodeId);
        engine.SetReady(node.NodeId, running && capable);
    }
}

void PollDocker(bool force = false)
{
    if (noDocker) return;
    if (dockerTask is { IsCompleted: true } done)
    {
        dockerTask = null;
        if (done.IsFaulted) Log("Docker probe failed: " + done.Exception!.GetBaseException().Message);
        else docker = done.Result;
        ApplyReadiness();
    }
    if (dockerTask is null && (force || DateTime.UtcNow >= nextProbe))
    {
        nextProbe = DateTime.UtcNow + probeInterval;
        dockerTask = Task.Run(() => probe.Probe());
    }
}

ApplyReadiness();
if (startLive) StartLiveFetch(false);

// ---- actions ------------------------------------------------------------------------------------
string Dropped(IReadOnlyList<string> dropped) =>
    dropped.Count == 0 ? "" : $" No longer placeable here: {string.Join(", ", dropped)} (released).";

void Reserve()
{
    var reservation = engine.Reserve();
    if (reservation is not null)
    {
        Log($"Reserved {reservation.SessionId} -> {reservation.NodeId} at {reservation.SiteId} " +
            $"({reservation.RecoverableHeatKwhPerHour:F2} kWh/h; site had {reservation.AvailableHeatKwhBeforeReservation:F2} kWh free).");
        return;
    }
    var nodes = engine.NodeViews();
    string reason = nodes.All(n => !n.Ready)
        ? (noDocker ? "no ready node (capability check?)" : "no ready node: is Docker running? (or use --no-docker)")
        : nodes.Where(n => n.Ready).All(n => n.Sessions.Count >= n.Node.SessionSlots)
            ? "every ready node's session slot is taken"
            : $"no ready node at a site with {engine.SessionHeatKwhPerHour:F2} kWh free heat capacity";
    Log("No placement: " + reason + ".");
}

void Step(int hours)
{
    if (mode != "replay") { Log("Hour steps only in replay mode (live follows the clock)."); return; }
    int moved = 0;
    for (; moved < hours && index + 1 < setup.Axis.Count; moved++)
    {
        history.Push((index, engine.Memory));
        engine.Advance(setup.ReplayHour(++index));
    }
    Log(moved == 0 ? "End of the scenario year." : $"Stepped {moved} h to {setup.Axis[index]}.");
}

void Back()
{
    if (mode != "replay" || history.Count == 0) { Log("Nothing to step back to."); return; }
    var (i, memory) = history.Pop();
    index = i;
    timeGeneration++;
    var dropped = engine.Begin(setup.ReplayHour(index), memory);
    Log($"Back to {setup.Axis[index]}; players re-placed in order." + Dropped(dropped));
}

void Jump(string label, string name)
{
    mode = "replay";
    timeGeneration++;
    history.Clear();
    index = setup.IndexOf(label);
    var dropped = engine.Begin(setup.ReplayHour(index));
    Log($"Jumped to {name} {label}, tanks empty; players re-placed in order." + Dropped(dropped));
}

// ---- rendering ----------------------------------------------------------------------------------
static string Kwh(double v) => v.ToString("F2", CultureInfo.InvariantCulture);
static string Esc(string s) => Markup.Escape(s);

// Keep source prose out of numeric tables so the normal view also fits an 80-column terminal.
string SiteLabel(string id) => "S" + (setup.NetworkSites.Keys.ToList().IndexOf(id) + 1);
string NodeLabel(string id) => id.StartsWith("session-", StringComparison.Ordinal) ? id[8..].ToUpperInvariant() : id;

IRenderable Render()
{
    var current = engine.Current!;
    var sites = engine.SiteViews();
    var nodes = engine.NodeViews();
    string modeText = current.Mode == "live" ? "[green]CURRENT WEATHER + MODEL[/]" : "[yellow]HISTORICAL REPLAY[/]";
    string clock = current.Mode == "live" ? "Zurich" : "dataset UTC+1";
    var header = new Markup(
        $"[bold]DigitalHeat | Gaming heat planner[/]  {modeText}\n" +
        $"{Esc(current.LocalLabel)} ({clock}) | {engine.Sessions.Count} reserved | {Kwh(engine.SessionHeatKwhPerHour)} kWh/h each (A-018)\n" +
        "[yellow]MODEL estimates, not heat/power measurements. No game is launched.[/]" +
        (checkCapabilities ? "" : "\n[red]WHAT-IF: application capability checks bypassed.[/]") +
        (noDocker ? "\n[yellow]NO DOCKER: containers assumed running; no observations.[/]" : ""));

    var nodeTable = new Table().Border(TableBorder.Simple).Title("[bold]Nodes | observed state vs reserved model heat[/]");
    foreach (var column in new[] { "Node / site", "Container", "Game", "Eligible", "Slots", "Reserved\nkWh/h" })
        nodeTable.AddColumn(column);
    foreach (var n in nodes)
    {
        docker.TryGetValue(n.Node.NodeId, out var d);
        string state = noDocker ? "[grey]assumed[/]" : d is null ? "[grey]pending[/]" : d.ContainerRunning ? "[green]running[/]" : "[red]unavailable[/]";
        string game = setup.IncompatibleNodes.ContainsKey(n.Node.NodeId) ? "not set up" : noDocker || d?.ApplicationRunning is null ? "unknown" : d.ApplicationRunning.Value ? "observed" : "not seen";
        nodeTable.AddRow($"[bold]{Esc(NodeLabel(n.Node.NodeId))}[/] / {SiteLabel(n.Node.SiteId)}", state, game,
            n.Ready ? "[green]yes[/]" : "[grey]no[/]", $"{n.Sessions.Count}/{n.Node.SessionSlots}", Kwh(n.GenerationKwh));
    }

    var siteTable = new Table().Border(TableBorder.Simple).Title("[bold]Sites | model preview for one full hour (kWh)[/]");
    foreach (var column in new[] { "Site", "Need", "Reserved", "Tank now\n/ max", "Unused", "Backup" }) siteTable.AddColumn(column);
    foreach (var v in sites)
        siteTable.AddRow($"[bold]{SiteLabel(v.Site.Id)}[/]", $"[deepskyblue1]{Kwh(v.Hour.Demand.TotalHeatKwh)}[/]", Kwh(v.GenerationKwh),
            $"{v.TankStoredKwh:F1} / {v.Site.TankCapacityKwh:F1}",
            v.Preview.DumpedHeatKwh > 0 ? $"[red]{Kwh(v.Preview.DumpedHeatKwh)}[/]" : "0.00", Kwh(v.Preview.BackupHeatKwh));

    var legend = new Markup(string.Join("\n", sites.Select(v =>
        $"[bold]{SiteLabel(v.Site.Id)}[/] {Esc(v.Site.Name)} | {(v.Hour.TemperatureC is {} t ? $"{t:F1} C" : "weather n/a")}")));
    var totals = new Markup($"[bold]All sites:[/] need {sites.Sum(v => v.Hour.Demand.TotalHeatKwh):F2} | reserved {sites.Sum(v => v.GenerationKwh):F2} | " +
        $"backup {sites.Sum(v => v.Preview.BackupHeatKwh):F2} kWh\n" +
        (current.Mode == "live" ? "[grey]Current forecast; other-site demand stays historical. Annual tariff.[/]" : "[grey]Historical weather + modelled buildings; annual tariff, not spot price.[/]") +
        (sites.Any(v => v.Hour.PriceSource.Contains("fallback", StringComparison.Ordinal)) ? "\n[yellow]Tariff fetch unavailable: using committed snapshot (S for sources).[/]" : ""));
    var resources = new Markup("[grey]Observed CPU / RAM used: " + string.Join(" | ", nodes.Select(n =>
    {
        docker.TryGetValue(n.Node.NodeId, out var state);
        string memory = state?.MemoryUsage?.Split('/')[0].Trim() ?? "n/a";
        return $"{Esc(NodeLabel(n.Node.NodeId))} {Esc(state?.CpuPercent ?? "n/a")} / {Esc(memory)}";
    })) + "[/]");
    var rows = new List<IRenderable> { new Panel(header).Expand(), nodeTable, resources, siteTable, legend, totals };
    if (showDetails)
    {
        foreach (var v in sites)
        {
            var historyData = setup.NetworkSites[v.Site.Id].Demand;
            double annual = historyData.Sum(h => h.TotalHeatKwh), peak = historyData.Max(h => h.TotalHeatKwh);
            rows.Add(new Panel(new Markup(
                $"[bold]{Esc(v.Site.Id)}[/]\n" +
                $"Space {v.Hour.Demand.SpaceHeatKwh:F2} + water {v.Hour.Demand.HotWaterKwh:F2} = {v.Hour.Demand.TotalHeatKwh:F2} kWh\n" +
                $"Reserve headroom: {v.FreeCapacityKwh:F2} kWh (need + free tank - held heat)\n" +
                $"{setup.Axis[0][..4]} dataset: {annual:N0} kWh/year | peak {peak:F2} kWh/h\n" +
                $"Tariff {v.Hour.ElectricityPriceChfPerKwh:F4} CHF/kWh | heat value {v.Hour.HeatValueChfPerKwh:F4} CHF/kWh\n" +
                $"Potential heat value {v.UsefulValueChfPerHour:F3} CHF/h includes tank charging; not profit.\n" +
                $"Closed model hours {v.Totals.Hours}: direct+stored {v.Totals.UsefulKwh:F2}, unused {v.Totals.DumpedKwh:F2}, backup {v.Totals.BackupKwh:F2} kWh\n" +
                $"Demand: {Esc(v.Hour.DemandSource)}\nTariff: {Esc(v.Hour.PriceSource)}"))
                .Header(SiteLabel(v.Site.Id)).Expand());
        }
        foreach (var node in setup.Config.Nodes)
        {
            string reason = setup.IncompatibleNodes.TryGetValue(node.NodeId, out var why) ? why : "declared compatible (not a measured capacity)";
            string detail = docker.TryGetValue(node.NodeId, out var observed) ? observed.Detail : "no observation";
            rows.Add(new Markup($"[grey]{Esc(node.NodeId)}: {Esc(reason)}; {Esc(detail)}[/]"));
        }
        rows.Add(new Markup("[yellow]Hourly what-if: final held sessions apply for the full hour, even when Docker is unavailable.\n" +
            "Only reservations create model heat; an observed game alone does not. Sites share one physical laptop.\n" +
            "Reference-house case formula; other building demands/sizes are synthetic, not meter readings.[/]"));
    }
    rows.Add(new Panel(new Markup(string.Join("\n", log.TakeLast(showDetails ? 7 : 2).Select(Esc)))).Header("Events").Expand());
    rows.Add(new Markup("[bold]R[/] reserve  [bold]X[/] release  [bold]N/Right[/] +1h  [bold]F[/] +24h  [bold]B/Left[/] back\n" +
        "[bold]J/U[/] Jan/Jul  [bold]L[/] weather mode  [bold]D[/] Docker  [bold]C[/] what-if  [bold]S[/] details  [bold]Q[/] quit"));
    return new Rows(rows);
}

void InitialReservations()
{
    for (int i = 0; i < initialSessions; i++) Reserve();
}

if (once || Console.IsInputRedirected)
{
    if (liveTask is not null) { liveTask.GetAwaiter().GetResult(); CompleteLiveFetch(); }
    if (!noDocker) { docker = probe.Probe(); ApplyReadiness(); }
    InitialReservations();
    AnsiConsole.Write(Render());
    return 0;
}

// Initial requested sessions wait for the initial observation/weather instead of failing against pending state.
if (liveTask is not null) { liveTask.GetAwaiter().GetResult(); CompleteLiveFetch(); }
if (!noDocker) { docker = probe.Probe(); ApplyReadiness(); }
InitialReservations();
bool running = true;
DateTime nextRender = DateTime.MinValue;
AnsiConsole.Live(Render()).AutoClear(false).Overflow(VerticalOverflow.Ellipsis).Start(ctx =>
{
    while (running)
    {
        bool dirty = false;
        PollDocker();
        if (liveTask is { IsCompleted: true }) { CompleteLiveFetch(); dirty = true; }
        if (mode == "live" && liveTask is null && engine.Current is { } now && DateTimeOffset.UtcNow >= now.IntervalStartUtc.AddHours(1))
            StartLiveFetch(true);
        while (Console.KeyAvailable)
        {
            var key = Console.ReadKey(intercept: true);
            dirty = true;
            switch (key.Key)
            {
                case ConsoleKey.R: Reserve(); break;
                case ConsoleKey.X: Log(engine.ReleaseLast() is { } id ? $"Released {id}." : "No session to release."); break;
                case ConsoleKey.RightArrow or ConsoleKey.N: Step(1); break;
                case ConsoleKey.F: Step(24); break;
                case ConsoleKey.LeftArrow or ConsoleKey.B: Back(); break;
                case ConsoleKey.J: Jump(setup.Config.WinterJumpLocal, "January"); break;
                case ConsoleKey.U: Jump(setup.Config.SummerJumpLocal, "July"); break;
                case ConsoleKey.L:
                    if (mode == "live") Jump(setup.Config.ReplayStartLocal, "replay start");
                    else StartLiveFetch(false);
                    break;
                case ConsoleKey.D: PollDocker(force: true); Log(noDocker ? "Docker disabled (--no-docker)." : "Docker probe requested."); break;
                case ConsoleKey.C:
                    checkCapabilities = !checkCapabilities; ApplyReadiness();
                    Log(checkCapabilities ? "Capability check on." : "WHAT-IF: capability check off; placement may pick nodes without Xonotic.");
                    break;
                case ConsoleKey.S: showDetails = !showDetails; break;
                case ConsoleKey.Q or ConsoleKey.Escape: running = false; break;
            }
        }
        if (dirty || DateTime.UtcNow >= nextRender)
        {
            ctx.UpdateTarget(Render());
            nextRender = DateTime.UtcNow.AddSeconds(1);
        }
        Thread.Sleep(50);
    }
});
return 0;
